    base=3*g
    for a,b in [(0,1),(0,2),(1,2)]: edges.append((base+a,base+b)); names.append(('in',g,a,b))
for g in range(n-1):
    for i in range(k): edges.append((3*g+i,3*(g+1)+i)); names.append(('bt',g,i))
diffs=[abs(labels[u]-labels[v]) for u,v in edges]
from collections import Counter
c=Counter(diffs)
print('dups',[d for d,v in c.items() if v>1], 'missing',[d for d in range(1,52) if d not in c])
for ei,d in enumerate(diffs):
    if c[d]>1 or d in []:
        print(ei,names[ei],edges[ei],labels[edges[ei][0]],labels[edges[ei][1]],d)
print(list(enumerate(diffs)))
